pub fn ostream_double(v: f64) -> String { ostream_double_prec(v, 6) }

pub fn ostream_double_prec(v: f64, precision: usize) -> String {
    let neg = v.is_sign_negative();
    if v.is_nan() { return if neg { "-nan".into() } else { "nan".into() }; }
    if v.is_infinite() { return if neg { "-inf".into() } else { "inf".into() }; }
    let p = if precision == 0 { 1 } else { precision };

    // Round to `p` significant digits via scientific form; recover the decimal exponent.
    let sci = format!("{:.*e}", p - 1, v);
    let (mant, exp_s) = sci.split_once('e').unwrap();
    let exp: i32 = exp_s.parse().unwrap();

    if exp < -4 || exp >= p as i32 {
        let m = trim_frac(mant);
        let (esign, eabs) = if exp < 0 { ('-', -(exp as i64)) } else { ('+', exp as i64) };
        format!("{}e{}{:02}", m, esign, eabs)
    } else {
        let decimals = (p as i32 - 1 - exp).max(0) as usize;
        trim_frac(&format!("{:.*}", decimals, v))
    }
}

fn trim_frac(s: &str) -> String {
    if !s.contains('.') { return s.to_string(); }
    let t = s.trim_end_matches('0');
    t.strip_suffix('.').unwrap_or(t).to_string()
}

fn main() {
    let mut args = std::env::args().skip(1);
    while let Some(a) = args.next() {
        let v: f64 = if a == "nan" { f64::NAN } else if a == "inf" { f64::INFINITY }
                     else if a == "-inf" { f64::NEG_INFINITY } else { a.parse().unwrap() };
        println!("{}", ostream_double(v));
    }
}
