// Independent ground-truth oracle for polygon-set union area (NonZero / EvenOdd / Positive / Negative).
// Deliberately written with a totally different method than the Rust engine under test:
//   * rectilinear inputs -> exact area by coordinate compression over an implicit grid
//   * general inputs     -> vertical slab (trapezoid) decomposition using long double
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <vector>
#include <string>
#include <algorithm>
#include <random>
#include <iostream>
#include <fstream>
using namespace std;
typedef long long ll;
typedef long double ld;

struct Pt { ll x, y; };
typedef vector<Pt> Poly;

static int fillMode = 1; // 0 evenodd, 1 nonzero, 2 positive, 3 negative
static bool insideRule(ll w) {
  switch (fillMode) {
    case 0: return (w & 1) != 0;
    case 1: return w != 0;
    case 2: return w > 0;
    default: return w < 0;
  }
}

// ---------- exact rectilinear path: coordinate compression ----------
// Valid when every edge is axis-aligned: all crossings land on lattice lines.
static bool allAxisAligned(const vector<Poly>& ps) {
  for (const auto& p : ps) {
    size_t n = p.size();
    for (size_t i = 0; i < n; i++) {
      const Pt& a = p[i]; const Pt& b = p[(i + 1) % n];
      if (a.x != b.x && a.y != b.y) return false;
    }
  }
  return true;
}

// winding number of point (px,py) w.r.t. one ring, standard crossing rule
static ll windingRing(const Poly& p, ld px, ld py) {
  ll w = 0; size_t n = p.size();
  for (size_t i = 0; i < n; i++) {
    ld x1 = (ld)p[i].x, y1 = (ld)p[i].y;
    ld x2 = (ld)p[(i + 1) % n].x, y2 = (ld)p[(i + 1) % n].y;
    if (y1 <= py) {
      if (y2 > py) { // upward crossing
        ld cr = (x2 - x1) * (py - y1) - (px - x1) * (y2 - y1);
        if (cr > 0) w++;
      }
    } else {
      if (y2 <= py) { // downward crossing
        ld cr = (x2 - x1) * (py - y1) - (px - x1) * (y2 - y1);
        if (cr < 0) w--;
      }
    }
  }
  return w;
}
static ll windingAll(const vector<Poly>& ps, ld px, ld py) {
  ll w = 0; for (const auto& p : ps) w += windingRing(p, px, py); return w;
}

static ld areaRectilinear(const vector<Poly>& ps) {
  vector<ll> xs, ys;
  for (const auto& p : ps) for (const auto& q : p) { xs.push_back(q.x); ys.push_back(q.y); }
  sort(xs.begin(), xs.end()); xs.erase(unique(xs.begin(), xs.end()), xs.end());
  sort(ys.begin(), ys.end()); ys.erase(unique(ys.begin(), ys.end()), ys.end());
  ld total = 0;
  for (size_t i = 0; i + 1 < xs.size(); i++) {
    for (size_t j = 0; j + 1 < ys.size(); j++) {
      ld cx = ((ld)xs[i] + (ld)xs[i + 1]) / 2, cy = ((ld)ys[j] + (ld)ys[j + 1]) / 2;
      if (insideRule(windingAll(ps, cx, cy)))
        total += (ld)(xs[i + 1] - xs[i]) * (ld)(ys[j + 1] - ys[j]);
    }
  }
  return total;
}

// ---------- general path: vertical slab / trapezoid decomposition ----------
struct Seg { ld x1, y1, x2, y2; int dir; }; // x1 < x2 ; dir=+1 if original went left->right upward-ish
static ld yAt(const Seg& s, ld x) {
  if (s.x2 == s.x1) return s.y1;
  return s.y1 + (s.y2 - s.y1) * (x - s.x1) / (s.x2 - s.x1);
}
static ld areaGeneral(const vector<Poly>& ps) {
  vector<Seg> segs;
  for (const auto& p : ps) {
    size_t n = p.size();
    for (size_t i = 0; i < n; i++) {
      Pt a = p[i], b = p[(i + 1) % n];
      if (a.x == b.x) continue;              // vertical edges contribute no area band
      int dir = 1;
      if (a.x > b.x) { swap(a, b); dir = -1; } // dir: winding contribution sign
      segs.push_back({(ld)a.x, (ld)a.y, (ld)b.x, (ld)b.y, dir});
    }
  }
  vector<ld> crit;
  for (const auto& p : ps) for (const auto& q : p) crit.push_back((ld)q.x);
  // add x of every pairwise segment intersection
  for (size_t i = 0; i < segs.size(); i++)
    for (size_t j = i + 1; j < segs.size(); j++) {
      const Seg& A = segs[i]; const Seg& B = segs[j];
      ld dax = A.x2 - A.x1, day = A.y2 - A.y1, dbx = B.x2 - B.x1, dby = B.y2 - B.y1;
      ld den = dax * dby - day * dbx;
      if (fabsl(den) < 1e-18L) continue;
      ld t = ((B.x1 - A.x1) * dby - (B.y1 - A.y1) * dbx) / den;
      ld x = A.x1 + t * dax;
      ld lo = max(A.x1, B.x1), hi = min(A.x2, B.x2);
      if (x > lo && x < hi) crit.push_back(x);
    }
  sort(crit.begin(), crit.end());
  crit.erase(unique(crit.begin(), crit.end()), crit.end());
  ld total = 0;
  for (size_t k = 0; k + 1 < crit.size(); k++) {
    ld x0 = crit[k], x1 = crit[k + 1];
    if (!(x1 > x0)) continue;
    ld xm = (x0 + x1) / 2;
    struct E { ld ym; int dir; ld y0, y1; };
    vector<E> es;
    for (const auto& s : segs)
      if (s.x1 <= x0 + 0 && s.x2 >= x1) // spans the whole slab
        es.push_back({yAt(s, xm), s.dir, yAt(s, x0), yAt(s, x1)});
    sort(es.begin(), es.end(), [](const E& a, const E& b) { return a.ym < b.ym; });
    ll w = 0;
    for (size_t i = 0; i + 1 < es.size(); i++) {
      w += es[i].dir;
      if (insideRule(w)) {
        ld h0 = es[i + 1].y0 - es[i].y0, h1 = es[i + 1].y1 - es[i].y1;
        total += (h0 + h1) / 2 * (x1 - x0);
      }
    }
  }
  return total;
}

static vector<Poly> readPolys(istream& in) {
  int n; if (!(in >> n)) return {};
  vector<Poly> ps(n);
  for (int i = 0; i < n; i++) { int m; in >> m; ps[i].resize(m); for (int j = 0; j < m; j++) in >> ps[i][j].x >> ps[i][j].y; }
  return ps;
}
static void writePolys(ostream& out, const vector<Poly>& ps) {
  out << ps.size() << "\n";
  for (const auto& p : ps) { out << p.size() << "\n"; for (const auto& q : p) out << q.x << " " << q.y << "\n"; }
}

int main(int argc, char** argv) {
  if (argc < 2) { fprintf(stderr, "usage: oracle gen <seed> <mode> | oracle area <file> [fillrule]\n"); return 2; }
  string cmd = argv[1];
  if (cmd == "gen") {
    unsigned long seed = strtoul(argv[2], 0, 10);
    string mode = argc > 3 ? argv[3] : "rects";
    mt19937_64 rng(seed);
    int n = 2 + (int)(rng() % 5);
    vector<Poly> ps;
    if (mode == "rects") {
      for (int i = 0; i < n; i++) {
        ll x0 = (ll)(rng() % 40), y0 = (ll)(rng() % 40);
        ll w = 1 + (ll)(rng() % 25), h = 1 + (ll)(rng() % 25);
        Poly p = {{x0, y0}, {x0 + w, y0}, {x0 + w, y0 + h}, {x0, y0 + h}};
        if (rng() % 2) reverse(p.begin(), p.end());
        ps.push_back(p);
      }
    } else if (mode == "recti") { // rectilinear staircase rings
      for (int i = 0; i < n; i++) {
        int steps = 2 + (int)(rng() % 5);
        ll x = (ll)(rng() % 30), y = (ll)(rng() % 30);
        Poly p; p.push_back({x, y});
        for (int s = 0; s < steps; s++) {
          x += 1 + (ll)(rng() % 12); p.push_back({x, y});
          y += 1 + (ll)(rng() % 12); p.push_back({x, y});
        }
        ll bx = p[0].x, by = p[0].y;
        p.push_back({bx, y});
        (void)bx; (void)by;
        ps.push_back(p);
      }
    } else { // general
      for (int i = 0; i < n; i++) {
        int m = 3 + (int)(rng() % 6);
        Poly p;
        for (int j = 0; j < m; j++) p.push_back({(ll)(rng() % 60), (ll)(rng() % 60)});
        ps.push_back(p);
      }
    }
    writePolys(cout, ps);
    return 0;
  }
  if (cmd == "area") {
    ifstream f(argv[2]);
    if (argc > 3) fillMode = atoi(argv[3]);
    vector<Poly> ps = readPolys(f);
    ld a = allAxisAligned(ps) ? areaRectilinear(ps) : areaGeneral(ps);
    printf("%.10Lf\n", a);
    return 0;
  }
  return 2;
}
